def _num(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)

def deep_merge(a, b):
    out = dict(a)
    for k, bv in b.items():
        if k not in out:
            out[k] = bv
        elif isinstance(out[k], dict) and isinstance(bv, dict):
            out[k] = deep_merge(out[k], bv)
        elif _num(out[k]) and _num(bv):
            out[k] = out[k] + bv
        else:
            out[k] = bv
    return out

def _coerce(v):
    low = v.lower()
    if low == "true":
        return True
    if low == "false":
        return False
    try:
        return int(v)
    except ValueError:
        pass
    try:
        return float(v)
    except ValueError:
        return v

def parse_kv(s):
    out = {}
    for seg in s.split(";"):
        seg = seg.strip()
        if not seg:
            continue
        if "=" not in seg:
            raise ValueError(f"missing '=' in segment: {seg!r}")
        k, v = seg.split("=", 1)
        out[k.strip()] = _coerce(v.strip())
    return out

PAIRS = {")": "(", "]": "[", "}": "{"}

def check_brackets(s):
    stack = []
    for i, ch in enumerate(s):
        if ch in "([{":
            stack.append((i, ch))
        elif ch in PAIRS:
            if not stack or stack[-1][1] != PAIRS[ch]:
                return i
            stack.pop()
    if stack:
        return stack[-1][0]
    return None

def merge_intervals(spans):
    if not spans:
        return []
    out = []
    for start, end in sorted(spans):
        if out and start <= out[-1][1]:
            out[-1] = (out[-1][0], max(out[-1][1], end))
        else:
            out.append((start, end))
    return out

