def clean(rows):
    out, report = [], {}

    def fail(why):
        report[why] = report.get(why, 0) + 1

    for row in rows:
        name = str(row.get("name") or "").strip().lower()
        if not name:
            fail("no name")
            continue
        raw = row.get("amount")
        try:
            amount = float(str(raw).replace("$", "").replace(",", "").strip())
        except (ValueError, TypeError):
            fail("bad amount")
            continue
        if amount < 0:
            fail("negative")
            continue
        out.append({"name": name, "amount": amount})
    return out, report

import re

PAT = re.compile(r"^(\S+) (\S+) (\S+) took=(\d+)ms(?: msg=(.*))?$")

def parse_logs(lines):
    records, by_level = [], {}
    for line in lines:
        m = PAT.match(line.strip())
        if not m:
            continue
        rec = {
            "ts": m.group(1),
            "level": m.group(2),
            "logger": m.group(3),
            "took_ms": int(m.group(4)),
            "msg": m.group(5) or "",
        }
        records.append(rec)
        by_level[rec["level"]] = by_level.get(rec["level"], 0) + 1
    vals = sorted(r["took_ms"] for r in records)
    p50 = vals[(len(vals) - 1) // 2] if vals else None
    return {"records": records, "by_level": by_level, "p50_ms": p50}

def flatten_json(obj, sep="."):
    out = {}

    def walk(node, prefix):
        if isinstance(node, dict) and node:
            for k, v in node.items():
                walk(v, prefix + sep + str(k) if prefix else str(k))
        elif isinstance(node, list) and node:
            for i, v in enumerate(node):
                walk(v, prefix + sep + str(i) if prefix else str(i))
        else:
            out[prefix] = node

    walk(obj, "")
    return out

