def chunk_sentences(sentences, max_chars, overlap):
    if max_chars < 1:
        raise ValueError("max_chars must be >= 1")
    if overlap < 0:
        raise ValueError("overlap must be >= 0")

    chunks, cur = [], []
    for s in sentences:
        candidate = cur + [s]
        if cur and len(" ".join(candidate)) > max_chars:
            chunks.append(" ".join(cur))
            cur = cur[-overlap:] if overlap else []
            # 重叠部分自己就装不下新句时，放弃重叠
            if cur and len(" ".join(cur + [s])) > max_chars:
                cur = []
        cur.append(s)
    if cur:
        chunks.append(" ".join(cur))
    return chunks

