import re
from collections import Counter

def _tok(s):
    return re.findall(r"[a-z0-9]+", s.lower())

def search(docs, query, k):
    terms = list(dict.fromkeys(_tok(query)))
    if not terms:
        return []
    scored = []
    for doc_id, text in docs.items():
        counts = Counter(_tok(text))
        hits = [counts[t] for t in terms if counts[t] > 0]
        if not hits:
            continue
        scored.append((doc_id, len(hits), sum(hits)))
    scored.sort(key=lambda r: (-r[1], -r[2], r[0]))
    return scored[:k]

