import time, functools

def with_retry(max_attempts=3, base=0.5, retry_on=(Exception,), sleeper=None):
    sleep = sleeper if sleeper is not None else time.sleep

    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            for i in range(max_attempts):
                try:
                    return fn(*args, **kwargs)
                except retry_on:
                    if i == max_attempts - 1:
                        raise
                    sleep(base * 2 ** i)
        return wrapper
    return deco

def trim(messages, budget, count):
    if not messages:
        return []
    head, rest = [], list(messages)
    if messages[0]["role"] == "system":
        head, rest = [messages[0]], list(messages[1:])

    used = sum(count(m["content"]) for m in head)
    kept = []
    for m in reversed(rest):
        cost = count(m["content"])
        if used + cost > budget:
            break
        used += cost
        kept.append(m)
    return head + list(reversed(kept))

