def dedupe_stream(events, window):
    if window < 0:
        raise ValueError("window must be >= 0")
    last = {}
    out = []
    for ts, key, payload in events:
        if key in last and ts - last[key] <= window:
            continue
        last[key] = ts
        out.append((ts, key, payload))
    return out

def _rate(d):
    return sum(1 for v in d.values() if v) / len(d) if d else 0.0

def diff_runs(before, after):
    shared = set(before) & set(after)
    return {
        "regressions": sorted(c for c in shared if before[c] and not after[c]),
        "fixes": sorted(c for c in shared if not before[c] and after[c]),
        "added": sorted(set(after) - set(before)),
        "removed": sorted(set(before) - set(after)),
        "pass_rate_delta": round(_rate(after) - _rate(before), 4),
    }
